create table auth_providers (id uuid not null, user_id uuid, provider_id varchar(255), provider_type varchar(255) check ((provider_type in ('LOCAL','GOOGLE'))), primary key (id));
create table email_verification_tokens (expires_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null, token_hash varchar(64) not null unique, primary key (id));
create table fuel (amount numeric(12,3), cost numeric(12,2), date date, mileage integer, created_at timestamp(6) with time zone not null, deleted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, vehicle_id uuid not null, currency varchar(20) check ((currency in ('EURO','US_DOLLAR','ZLOTY','HRYVNIA'))), gas_station varchar(50), primary key (id));
create table google_link_tokens (expires_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null, token_hash varchar(64) not null unique, provider_id varchar(255) not null, primary key (id));
create table maintenance (cost numeric(12,2), mileage integer, service_date date, created_at timestamp(6) with time zone not null, deleted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, vehicle_id uuid not null, currency varchar(20) check ((currency in ('EURO','US_DOLLAR','ZLOTY','HRYVNIA'))), title varchar(50), category varchar(255), description TEXT, primary key (id));
create table maintenance_attachments (created_at timestamp(6) with time zone not null, deleted_at timestamp(6) with time zone, size_bytes bigint, id uuid not null, maintenance_id uuid not null, content_type varchar(100), object_key varchar(512) not null, url varchar(1024), file_name varchar(255) not null, primary key (id));
create table password_reset_tokens (expires_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null, token_hash varchar(64) not null unique, primary key (id));
create table refresh_tokens (revoked boolean not null, expires_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null, token varchar(128) not null unique, primary key (id));
create table share_links (include_attachments boolean not null, include_image boolean not null, revoked boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, created_by uuid not null, id uuid not null, vehicle_id uuid not null, token varchar(128) not null unique, primary key (id));
create table users (demo boolean not null, email_verified boolean not null, id uuid not null, email varchar(255) not null unique, password varchar(255), primary key (id));
create table vehicle (mileage integer, year integer, deleted_at timestamp(6) with time zone, id uuid not null, user_id uuid not null, fuel_type varchar(20) check ((fuel_type in ('PETROL','DIESEL','ELECTRIC','HYBRID','LPG'))), license_plate varchar(20), make varchar(60), model varchar(60), image TEXT, primary key (id));
create index idx_fuel_vehicle_date on fuel (vehicle_id, date);
create index idx_fuel_vehicle_cost on fuel (vehicle_id, cost);
create index idx_fuel_vehicle_active on fuel (vehicle_id, deleted_at);
create index idx_maintenance_vehicle_date on maintenance (vehicle_id, service_date);
create index idx_maintenance_vehicle_cost on maintenance (vehicle_id, cost);
create index idx_maintenance_vehicle_active on maintenance (vehicle_id, deleted_at);
create index idx_maintenance_attachment_maintenance_id on maintenance_attachments (maintenance_id);
create index idx_share_links_vehicle_created_by on share_links (vehicle_id, created_by);
create index idx_vehicle_user_active on vehicle (user_id, deleted_at);
