alter table if exists email_verification_tokens add constraint FKi1c4mmamlb8keqt74k4lrtwhc foreign key (user_id) references users;
alter table if exists fuel add constraint FKcsj8bx4ew5bbufbsh3ad5hpx6 foreign key (vehicle_id) references vehicle;
